// The files `init` writes. Each starts with GENERATED, so `--force` overwrites only files init wrote.

/** The first line of every generated file. */
export const GENERATED = '// generated by @foliwake/next init — edit freely';

/** The language of the app's files. */
export type Lang = 'ts' | 'js';

const lines = (...rows: string[]): string => `${rows.join('\n')}\n`;

/** `app/foliwake/[...path]/route.ts`: code, media, hook and health; preview behind isAuthor with --preview. */
export function routeFile(authorImport: string | null): string {
  if (authorImport === null) return lines(GENERATED, "export { GET, HEAD, POST } from '@foliwake/next/handler';");
  return lines(
    GENERATED,
    "import { createFoliwakeHandler } from '@foliwake/next/handler';",
    `import { isAuthor } from '${authorImport}';`,
    '',
    'export const { GET, HEAD, POST } = createFoliwakeHandler({ authorizePreview: isAuthor });',
  );
}

/** The live page route: one line at the root, a mounted factory otherwise. */
export function livePageFile(mount: string | null): string {
  if (mount === null) return lines(GENERATED, "export { default, generateMetadata } from '@foliwake/next/page';");
  return lines(
    GENERATED,
    "import { createFoliwakePage } from '@foliwake/next/page';",
    '',
    `const Page = createFoliwakePage({ mount: '${mount}' });`,
    '',
    'export default Page;',
    'export const generateMetadata = Page.generateMetadata;',
  );
}

/** The preview page route under `/preview`, behind isAuthor. */
export function previewPageFile(authorImport: string): string {
  return lines(
    GENERATED,
    "import { createFoliwakePage } from '@foliwake/next/page';",
    `import { isAuthor } from '${authorImport}';`,
    '',
    "const Page = createFoliwakePage({ channel: 'preview', authorize: isAuthor, mount: '/preview' });",
    '',
    'export default Page;',
    'export const generateMetadata = Page.generateMetadata;',
  );
}

/** The author check stub: everyone while `next dev` runs, nobody in production, until the app replaces it. */
export function isAuthorFile(lang: Lang): string {
  const signature = lang === 'ts' ? 'export function isAuthor(): boolean {' : 'export function isAuthor() {';
  return lines(
    GENERATED,
    '// Replace this with your sign-in: who may see preview (unpublished) pages.',
    '// Development only: every visitor is an author under `next dev`; in production nobody is.',
    signature,
    "  return process.env.NODE_ENV === 'development';",
    '}',
  );
}

/** A new next.config. */
export function nextConfigFile(): string {
  return lines(
    "import { withFoliwake } from '@foliwake/next/config';",
    '',
    'export default withFoliwake({ cacheComponents: true });',
  );
}
